package com.yeyamo_mobile.api.recommendation_service.application.scoring;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.recommendation_service.domain.*;
@Component public class PreferenceScoringStrategy implements ScoringStrategy{public String name(){return"preferences";}public double score(Candidate c,RecommendationProfile p,RecommendationContext x){double s=Objects.equals(c.regionCode(),p.preferredRegion())&&c.regionCode()!=null?15:0;return s+Math.min(20,Math.max(0,p.categoryAffinity().getOrDefault(c.categoryCode(),0d))*2);}private static final class Objects{static boolean equals(Object a,Object b){return java.util.Objects.equals(a,b);}}}
